(function(){function copy(t){if(navigator.clipboard&&navigator.clipboard.writeText){return navigator.clipboard.writeText(t);}return new Promise(function(res,rej){try{var e=document.createElement('textarea');e.value=t;e.style.position='fixed';e.style.opacity='0';document.body.appendChild(e);e.select();document.execCommand('copy');document.body.removeChild(e);res();}catch(err){rej(err);}});}function artTitle(){var e=document.querySelector('.post-title')||document.querySelector('.blog-title');return e?e.textContent.trim():document.title;}function artUrl(){var c=document.querySelector('link[rel="canonical"]');return c?c.getAttribute('href'):location.href;}var T={link:function(t,u){return u;},wechat:function(t,u){return '链接：'+u+'\n（微信里粘贴给朋友，或搜「FreeNav」找到我们）';},weibo:function(t,u){return '推荐 @FreeNav 专栏《'+t+'》'+u+' #免费软件# #开源替代#';},xiaohongshu:function(t,u){return '最近在 FreeNav 读到一篇不错的：《'+t+'》。\nFreeNav 是个做「软件界豆瓣榜单」的站，人工精选免费 / 开源软件、深度测评、不追踪你。想看的搜「FreeNav」就能找到。';}};document.querySelectorAll('.share-bar').forEach(function(bar){bar.querySelectorAll('[data-share]').forEach(function(btn){btn.addEventListener('click',function(){var k=btn.getAttribute('data-share');if(k==='native'){if(navigator.share){navigator.share({title:artTitle(),url:artUrl()}).catch(function(){});}return;}var txt=T[k](artTitle(),artUrl());copy(txt).then(function(){var o=btn.textContent;btn.textContent='已复制 ✓';btn.classList.add('copied');setTimeout(function(){btn.textContent=o;btn.classList.remove('copied');},1600);}).catch(function(){btn.textContent='复制失败';setTimeout(function(){btn.textContent='复制链接';},1600);});});});});})();